import { LayoutDashboard, QrCode, CalendarDays, PenLine, BarChart3, BadgeDollarSign, FileCheck2, Users, GraduationCap, Settings2, LogOut, X, Plus, Search, Download, Printer, ChevronRight, RefreshCw, ArrowUpRight, Clock3 } from 'lucide-react'
